// Domain types shared by server and client.
// All documents use string ids (`_id`) generated by `newId()` on the server,
// so they serialize to JSON as-is. Dates become ISO strings over the wire.

import type {AiProviderId} from "../utils/ai-providers"

export type Role = "admin" | "assistant"

export const PROJECT_PERMISSIONS = ["analytics:read", "sessions:read", "questions:reply", "sources:manage", "settings:edit"] as const

export type ProjectPermission = (typeof PROJECT_PERMISSIONS)[number]

export const PERMISSION_INFO: Record<ProjectPermission, {label: string; description: string}> = {
    "analytics:read": {label: "Analytics", description: "View usage and performance analytics"},
    "sessions:read": {label: "Conversations", description: "Read chat sessions and messages"},
    "questions:reply": {label: "Escalated questions", description: "Reply to and dismiss escalated questions"},
    "sources:manage": {label: "Knowledge", description: "Manage FAQ, sources and trigger syncs"},
    "settings:edit": {label: "Settings", description: "Edit project settings, appearance and embedding"}
}

export interface ProjectAccess {
    projectId: string
    permissions: ProjectPermission[]
}

export interface User {
    _id: string
    email: string
    name: string
    avatar?: string
    role: Role
    /** Only relevant for assistants. Admins have full access to everything. */
    projects: ProjectAccess[]
    providers: {google?: string; microsoft?: string}
    disabled?: boolean
    createdAt: Date
    lastLoginAt?: Date
}

/** Optional webhook fired when a question is escalated. Disabled while `url` is empty. */
export interface EscalationWebhook {
    /** http(s) endpoint that receives the POST (must resolve publicly, like sources) */
    url: string
    /** Extra request headers, e.g. `Authorization` */
    headers: Record<string, string>
    /** JSON body template: `{{placeholder}}` renders a JSON value. Empty = the default body */
    bodyTemplate: string
}

export interface ChatTheme {
    mode: "light" | "dark"
    /** Primary accent (buttons, user bubbles, launcher) */
    accent: string
    /** Secondary accent (gradients, links) */
    accent2: string
    /** Highlight colour (focus rings, badges, source chips) */
    highlight: string
    botName: string
    welcomeMessage: string
    placeholder: string
    /** Launcher position for the JS embed */
    position: "right" | "left"
}

export interface Project {
    _id: string
    title: string
    website: string
    /** Project icon as a data URI (usually the website favicon). Falls back to the two-letter mark when unset. */
    icon?: string
    systemInstructions: string
    /** Model id of the configured AI provider, e.g. `openrouter/free`. Empty = the default model of the Global Settings. */
    model: string
    temperature: number
    /** Max user messages per chat session before redirecting to support. 0 = unlimited. */
    rateLimit: number
    supportEmail?: string
    supportDisplayName?: {useAdminName: boolean; customName: string}
    /** Domains allowed to embed the chat. Supports wildcards like `*.example.com`. The website domain is always allowed. */
    allowedDomains: string[]
    /** Default refresh interval for sources, in hours (1..336), or 0 for manual only. Default 168 (7 days). */
    refreshIntervalHours: number
    /** How much of the fetched content is indexed. Unset = `DEFAULT_INGEST_DETAIL`. */
    ingestDetail?: IngestDetail
    /** POSTed when a question is escalated. Unset or empty `url` disables it */
    escalationWebhook?: EscalationWebhook
    /** Show source code references under chat answers */
    showCodeSources: boolean
    theme: ChatTheme
    enabled: boolean
    createdAt: Date
    updatedAt: Date
}

export type SourceType = "url" | "git" | "drive"
export type SourceStatus = "idle" | "queued" | "syncing" | "error"

export interface SourceOptions {
    /** git: branch to clone (default: repo default branch) */
    branch?: string
    /** git: glob patterns of files to include (default: documentation files) */
    include?: string[]
    /** git: glob patterns to exclude */
    exclude?: string[]
    /** git: access token for private repos. NEVER returned to clients. */
    accessToken?: string
    /** git: index source code (default include patterns) and summarize it. Default true. */
    code?: boolean
    /** url: follow same-site links under the same path prefix */
    crawl?: boolean
    /** url: max pages when crawling (1..500) */
    maxPages?: number
    /** drive: service account JSON key overriding the global key. NEVER returned to clients. */
    serviceAccountKey?: string
}

export interface Source {
    _id: string
    projectId: string
    type: SourceType
    title: string
    url: string
    options: SourceOptions
    /** Per source refresh interval in hours (1..336), 0 = manual only, null = use the project's default. */
    refreshIntervalHours: number | null
    status: SourceStatus
    lastSyncAt?: Date
    nextSyncAt: Date
    lastError?: string
    lastDurationMs?: number
    /** git: commit and settings fingerprint of the last complete sync; the next sync skips cloning while it matches */
    syncedRevision?: string
    documentCount: number
    chunkCount: number
    createdAt: Date
    updatedAt: Date
}

/** A source as sent to clients: secret option values are stripped and exposed as `has*` flags instead. */
export type SourceView = Omit<Source, "options"> & {
    options: Omit<SourceOptions, "accessToken" | "serviceAccountKey"> & {
        hasAccessToken?: boolean
        hasServiceAccountKey?: boolean
        /** drive: client_email of the per-source service account key (not secret) */
        serviceAccountEmail?: string
    }
}

export interface Faq {
    _id: string
    projectId: string
    question: string
    answer: string
    /** Conversation this entry was learned from (finished sessions with human replies) */
    sessionId?: string
    createdAt: Date
    updatedAt: Date
}

export type ChunkSourceType = SourceType | "faq"

/** A fetched document (web page, repo file, Drive file) converted to markdown. */
export interface DocumentRecord {
    _id: string
    projectId: string
    sourceId: string
    /** URL for web pages, file path for git files, Drive file id for drive sources */
    ref: string
    url?: string
    title: string
    hash: string
    markdown: string
    /** Source-specific revision of the fetched content (Drive file version), used to skip unchanged files */
    version?: string
    chunkCount: number
    updatedAt: Date
}

export interface Chunk {
    _id: string
    projectId: string
    sourceId: string
    documentId: string
    sourceType: ChunkSourceType
    title: string
    url?: string
    heading?: string
    content: string
    hash: string
    embedding: number[]
    /** Embedding space of the vector: `model#dimensions` */
    embeddingModel: string
    tokens: number
    createdAt: Date
}

export interface ChatSession {
    _id: string
    projectId: string
    visitorName: string
    visitorEmail?: string
    tokenHash: string
    ipHash?: string
    userAgent?: string
    origin?: string
    userMessageCount: number
    messageCount: number
    unansweredCount: number
    limitReached: boolean
    /** Flagged as done by an admin or agent; a new message reopens the session automatically */
    finishedAt?: Date
    finishedBy?: {userId?: string; name: string; via: "admin" | "mcp"}
    /** Ended by the visitor (new conversation) or closed after `AppSettings.chatAutoCloseDays` without messages: nobody can post into it anymore */
    endedAt?: Date
    /** Why the session ended (unset on sessions ended by the visitor before it existed) */
    endReason?: "visitor" | "inactive"
    /** FAQ entry learned from this conversation the last time it was finished */
    learnedFaqId?: string
    /** Set when a human replied to an escalated question from the admin panel: the assistant stays silent until no question is open */
    humanHandledAt?: Date
    humanHandledBy?: {userId?: string; name: string}
    /** The "team didn't take over, answer comes by email" notice was posted into this chat at this time, or a takeover ended: older open questions get no notice */
    emailFallbackAt?: Date
    /** Last time the visitor had the chat open and visible */
    visitorSeenAt?: Date
    createdAt: Date
    lastMessageAt: Date
}

export type MessageRole = "user" | "assistant" | "agent"

export type MessageSourceKind = "docs" | "code"

export interface MessageSourceRef {
    title: string
    url?: string
    kind: MessageSourceKind
}

export interface ChatMessage {
    _id: string
    projectId: string
    sessionId: string
    role: MessageRole
    content: string
    sources?: MessageSourceRef[]
    /** True when the assistant could not answer confidently and the question was escalated */
    escalated?: boolean
    /** Automated notice: nobody took over the escalated chat in time, the answer will come by email */
    emailFallback?: boolean
    model?: string
    usage?: {promptTokens: number; completionTokens: number; cost?: number}
    latencyMs?: number
    /** For `agent` messages: human (admin UI) or bot (MCP) that replied */
    author?: {userId?: string; name: string; via: "admin" | "mcp"}
    questionId?: string
    createdAt: Date
}

export type QuestionStatus = "open" | "answered" | "dismissed"
export type QuestionReason = "low_confidence" | "rate_limit" | "user_request"

export interface Question {
    _id: string
    projectId: string
    sessionId: string
    messageId?: string
    question: string
    visitorName: string
    visitorEmail?: string
    reason: QuestionReason
    status: QuestionStatus
    answer?: string
    answeredBy?: {userId?: string; name: string; via: "admin" | "mcp"}
    answeredAt?: Date
    supportNotifiedAt?: Date
    /** The project's escalation webhook was delivered for this question */
    webhookSentAt?: Date
    visitorNotifiedAt?: Date
    /** The answer is emailed at this time unless the visitor sees the chat before */
    visitorEmailDueAt?: Date
    /** FAQ entry created from the answer */
    faqId?: string
    /** The AI decided the question only concerns this visitor (their account, order, data): its answer is not added to the FAQ by default */
    userSpecific?: boolean
    /** Set while the user-specific classification runs (cleared when it ends), so a reply on any server waits for its decision */
    classifyingAt?: Date
    createdAt: Date
    updatedAt: Date
}

/** What happened with the answer email: sent now, scheduled (visitor not in the chat), skipped (visitor is in the chat), or none (no email / disabled) */
export type AnswerEmailStatus = "sent" | "scheduled" | "seen" | "none" | "failed"

export interface ApiToken {
    _id: string
    userId: string
    name: string
    /** First characters of the token, for display */
    prefix: string
    tokenHash: string
    /** Optional project allowlist; unset = all projects the user can access */
    projectIds?: string[]
    /** Optional permission ceiling; unset = all permissions the user has on each project */
    permissions?: ProjectPermission[]
    /** Optional expiration timestamp; expired tokens are rejected */
    expiresAt?: Date
    lastUsedAt?: Date
    createdAt: Date
}

export type SyncRunStatus = "success" | "partial" | "failed"

/** One sync of a source. Deleted after `AppSettings.syncHistoryDays`. */
export interface SyncRun {
    _id: string
    projectId: string
    sourceId: string
    status: SyncRunStatus
    startedAt: Date
    finishedAt: Date
    durationMs: number
    /** Files/pages indexed for the source after the run (unset when the run failed) */
    documents?: number
    /** Total size of the indexed markdown after the run, in bytes (unset when the run failed) */
    bytes?: number
    chunks?: number
    /** Documents added or updated by this run */
    changed: number
    removed: number
    /** Chunks sent to the embedding model */
    embedded: number
    /** Failure reason, or the warnings of a partial run */
    message?: string
}

/** Push notifications a device can subscribe to */
export const PUSH_EVENTS = ["conversations", "escalations", "syncs"] as const

export type PushEvent = (typeof PUSH_EVENTS)[number]

/** Each notification goes only to users with this permission on the project */
export const PUSH_EVENT_INFO: Record<PushEvent, {label: string; description: string; permission: ProjectPermission}> = {
    conversations: {label: "New conversations", description: "A visitor started a conversation", permission: "sessions:read"},
    escalations: {label: "Escalated questions", description: "A visitor escalated a question. Priority: stays on screen until dismissed", permission: "questions:reply"},
    syncs: {label: "Knowledge syncs", description: "A knowledge source finished syncing", permission: "sources:manage"}
}

/** A browser / installed app subscribed to Web Push notifications of a user */
export interface PushDevice {
    /** sha256 (hex) of the endpoint */
    _id: string
    userId: string
    /** Push service URL of the subscription, unique per device and browser */
    endpoint: string
    keys: {p256dh: string; auth: string}
    events: PushEvent[]
    userAgent?: string
    createdAt: Date
    updatedAt: Date
}

/** Session payload stored in the sealed cookie (nuxt-auth-utils) */
export interface SessionUser {
    id: string
    email: string
    name: string
    avatar?: string
    role: Role
}

/** Workspace-wide settings, editable on the admin Global Settings page. Unset values fall back to environment variables. */
export interface AppSettings {
    /** Per AI provider: its API key. A provider with a key is enabled. Unsaved keys fall back to the environment. */
    aiProviders: Record<AiProviderId, AiProviderSettings>
    /** Base URL of the custom provider, e.g. http://localhost:11434/v1. The custom provider is enabled when it is set. */
    aiProviderBaseUrl: string
    /**
     * Before multiple providers were supported, the custom provider replaced OpenRouter. When set, model ids without a
     * provider prefix belong to the custom provider instead of OpenRouter. Read only (NUXT_CUSTOM_AI_PROVIDER or saved back then).
     */
    customAiProvider: boolean
    /** Embedding model id */
    embeddingModel: string
    /** Vector size produced by the embedding model (used by the vector index) */
    embeddingDimensions: number
    /** Send `dimensions` with embedding requests (shortened vectors). False = the model's native size. */
    embeddingDimensionsParam: boolean
    /** Chat model of the projects that have no model of their own */
    defaultModel: string
    /** Chat model used when a request to the project's (or task's) model fails. Empty = no fallback. */
    fallbackModel: string
    /** Small, cheap model for yes / no decisions, e.g. whether an escalated question is user specific. Empty = the project's chat model. */
    decisionModel: string
    /** Model that summarizes source code of git repositories. Empty disables summaries. */
    codeSummaryModel: string
    /** User-Agent of the website crawler. Empty = default `RAGPulseBot/1.0 (+url)`. */
    userAgent: string
    /** Minimum delay between two requests to the same website, in milliseconds */
    requestIntervalMs: number
    /** Days sync runs are kept in each source's history */
    syncHistoryDays: number
    /** Days escalated questions are kept (FAQ entries created from them are kept). 0 = forever. */
    questionRetentionDays: number
    /** System instructions applied to the chat of every project, with precedence over project instructions. Empty disables them. */
    globalInstructions: string
    /** Minutes an escalated chat waits for a team member to take over before telling the visitor the answer comes by email. 0 = right away. */
    humanTakeoverWaitMinutes: number
    /** Minutes to wait before emailing an answer to a visitor who is not in the chat (cancelled when they see it). 0 = right away. */
    answerEmailDelayMinutes: number
    /** Days without messages after which a chat session is closed (the visitor gets a new chat). 0 = never. */
    chatAutoCloseDays: number
}

/** Settings of one AI provider */
export interface AiProviderSettings {
    /** Sent as Bearer token, overrides its environment variable. Optional for the custom provider. NEVER sent to clients. */
    apiKey: string
    /** Fingerprint of the credentials (key, custom base URL) that passed the last test, empty when never tested */
    verified: string
}

/** AiProviderSettings as sent to clients: the API key is exposed as flags instead. */
export interface AiProviderView {
    /** A key is configured (saved in the settings or in the environment) */
    hasApiKey: boolean
    /** Credentials saved in the settings (the key, for the custom provider also the base URL) override the environment and can be removed */
    saved: boolean
    /** The environment variable with the key is set */
    envApiKey: boolean
    /** The current credentials passed a test. Settings can only be saved when every enabled provider is verified. */
    verified: boolean
}

/** AppSettings as sent to clients, without API keys. */
export type AppSettingsView = Omit<AppSettings, "aiProviders"> & {aiProviders: Record<AiProviderId, AiProviderView>}

/** Progress of re-embedding after an embedding model change */
export interface EmbeddingStatus {
    model: string
    total: number
    current: number
}

export const INGEST_DETAILS = ["compact", "balanced", "detailed"] as const

/** Ingestion preset: trades index size (storage, embeddings) for retrieval detail */
export type IngestDetail = (typeof INGEST_DETAILS)[number]

export const DEFAULT_INGEST_DETAIL: IngestDetail = "balanced"

export const INGEST_DETAIL_INFO: Record<IngestDetail, {label: string; description: string}> = {
    compact: {
        label: "Compact",
        description: "Smallest index, for lightweight databases. Keeps headings and lists only, short code summaries without source code, removes duplicated content."
    },
    balanced: {
        label: "Balanced",
        description: "Good answers at a moderate size. Clean markdown without exact duplicates, code summaries with the source code."
    },
    detailed: {
        label: "Detailed",
        description: "Most accurate, largest index. Keeps all markdown styles, in-depth code summaries with references and source comments, smaller chunks."
    }
}

/** Ingestion preset of a project (projects without one use the default). */
export function projectIngestDetail(project: {ingestDetail?: IngestDetail | null} | null | undefined): IngestDetail {
    const value = project?.ingestDetail
    return value && (INGEST_DETAILS as readonly string[]).includes(value) ? value : DEFAULT_INGEST_DETAIL
}

export const REFRESH_MIN_HOURS = 1
export const REFRESH_MAX_HOURS = 336
export const DEFAULT_REFRESH_HOURS = 168
/** Refresh interval of sources that only sync when requested */
export const MANUAL_REFRESH = 0
/** Refresh interval presets (hours) */
export const REFRESH_PRESETS = [2, 4, 12, 24, 48, 72, 168, 336]

/** Whether a refresh interval is valid: manual only, or 1 hour to 14 days. */
export function isRefreshInterval(hours: number): boolean {
    return hours === MANUAL_REFRESH || (Number.isInteger(hours) && hours >= REFRESH_MIN_HOURS && hours <= REFRESH_MAX_HOURS)
}

